<?php declare(strict_types=1); namespace App\Services; use Core\Database\DatabaseManager; final class AdminAccount { private const PERMISSIONS = [ 'products.view' => 'View products', 'products.manage' => 'Create, edit and delete products', 'categories.view' => 'View categories, collections and brands', 'categories.manage' => 'Manage categories, collections and brands', 'announcements.view' => 'View announcements', 'announcements.manage' => 'Create, edit and delete announcements', 'users.manage' => 'Manage users', 'permissions.manage' => 'Manage roles and permissions', 'languages.manage' => 'Manage languages', 'media.view' => 'View media library', 'media.manage' => 'Upload and delete media', 'settings.manage' => 'Manage platform settings', 'seo.manage' => 'Manage SEO defaults', 'notifications.view' => 'View notifications', ]; public function __construct( private readonly DatabaseManager $db, ) { } public function sync(string $email, string $password, string $adminName): void { $connection = $this->db->connection(); $now = date('Y-m-d H:i:s'); $displayName = $adminName !== '' ? $adminName : 'LUFLY Administrator'; $connection->transaction(function () use ($connection, $email, $password, $displayName, $now): void { $role = $connection->selectOne('SELECT id FROM roles WHERE name = ?', ['admin']); $roleId = $role !== null ? (int) $role['id'] : (int) $connection->table('roles')->insert([ 'name' => 'admin', 'description' => 'Full access to every module.', 'created_at' => $now, 'updated_at' => $now, ]); foreach (self::PERMISSIONS as $key => $label) { $permission = $connection->selectOne('SELECT id FROM permissions WHERE `key` = ?', [$key]); $permissionId = $permission !== null ? (int) $permission['id'] : (int) $connection->table('permissions')->insert([ 'key' => $key, 'name' => $label, 'description' => $label, 'created_at' => $now, 'updated_at' => $now, ]); $granted = $connection->selectOne( 'SELECT id FROM role_permissions WHERE role_id = ? AND permission_id = ?', [$roleId, $permissionId], ); if ($granted === null) { $connection->table('role_permissions')->insert([ 'role_id' => $roleId, 'permission_id' => $permissionId, 'created_at' => $now, 'updated_at' => $now, ]); } } $hash = password_hash($password, PASSWORD_BCRYPT, [ 'cost' => (int) config('security.bcrypt_cost', 12), ]); $existing = $connection->selectOne('SELECT id FROM users WHERE email = ?', [$email]); if ($existing !== null) { $userId = (int) $existing['id']; $connection->table('users')->where('id', $userId)->update([ 'name' => $displayName, 'password' => $hash, 'status' => 'active', 'deleted_at' => null, 'updated_at' => $now, ]); } else { $userId = (int) $connection->table('users')->insert([ 'name' => $displayName, 'email' => $email, 'password' => $hash, 'locale' => 'en', 'status' => 'active', 'created_at' => $now, 'updated_at' => $now, ]); } $connection->affect('DELETE FROM user_roles WHERE user_id = ? AND role_id != ?', [$userId, $roleId]); $hasRole = $connection->selectOne( 'SELECT id FROM user_roles WHERE user_id = ? AND role_id = ?', [$userId, $roleId], ); if ($hasRole === null) { $connection->table('user_roles')->insert([ 'user_id' => $userId, 'role_id' => $roleId, 'created_at' => $now, 'updated_at' => $now, ]); } $connection->affect( "UPDATE users SET status = 'inactive', updated_at = ? WHERE id != ? AND status != 'inactive'", [$now, $userId], ); }); } public function syncFromEnvIfMatches(string $email, string $password): ?string { $envEmail = strtolower(trim((string) env('ADMIN_EMAIL', ''))); $envPassword = (string) env('ADMIN_PASSWORD', ''); if (!filter_var($envEmail, FILTER_VALIDATE_EMAIL) || strlen($envPassword) < 14) { return null; } if (strtolower(trim($email)) !== $envEmail || !hash_equals($envPassword, $password)) { return null; } $this->sync($envEmail, $envPassword, trim((string) env('ADMIN_NAME', 'LUFLY Administrator'))); return $envEmail; } } 